INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "…ぷはーっ！", 13020011, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 0, "", "", "", 13020012, 93);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 3, "", "", 1, 13020013, 32);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 13020011, "", "", "", 13020014, 91);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "いかんいかん\n資材の山に埋もれて\nしまうところだった", 13020015, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 0, "", "", "", 13020016, 91);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (1, 302, 0, 0.2, "", 2, "NoItem", "", "nyx_302_yuni_02", 13020017, 3);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (1, 302, 0, 0.2, "", 111031, "nyx_idle_normal", 0.2, "nyx_302_yuni_02", 13020018, 3);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", 13020019, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 5, "", "", "", 13020020, 93);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 111031, "", "", 0, 13020021, 4);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 1, 0.2, "", 111031, "", "", "nyx_cmn_03", 13020022, 3);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 13020023, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 0, "", "", "", 13020024, 91);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 1, 0.2, "", 111031, "", "", "nyx_301_yuni_01", 13020025, 3);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 13020026, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 0, "", "", 1, 13020027, 91);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 13020028, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 0, "", "", 1, 13020029, 91);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (1, 302, 0, 0.2, "", 111031, "nyx_302_yuni_04", "", "nyx_302_yuni_03", 13020030, 3);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "是非もなし\nいざ往かん！", 13020031, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 0, "", "", 1, 13020032, 91);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 1.5, "", "", "", 13020033, 93);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, 10, "", "", 111031, "", "", "む。奥に入りすぎた\nこれは…出られぬ！\n誰かー！　誰か―！", 13020034, 11);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 302, "", "", "", 0, "", "", "", 13020035, 91);
